    new_email = StringField('New Email', validators=[DataRequired(), EqualTo('confirm_email')])  # We'll define this later
    confirm_email = StringField('Confirm New Email', validators=[DataRequired()])
    password = PasswordField('Password', validators=[DataRequired()])

@app.route('/change-email', methods=['GET', 'POST'])
