        form = ChangeEmailForm()
    return render_template('change-email.html', form=form)

class EqualTo(FlaskForm):
    def __init__(self, field_name):
        self.field_name = field_name

    def _value(self):
        return getattr(self._formdata, self.field_name)

    def __call__(self, formfield):
        v1 = self._value()
        v2 = formfield.get_value()
        if not (v1 == v2):
            raise ValidationError('New email and confirm new email must be the same')

if __name__ == '__main__':
    app.run(debug=True)
