#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main() {
    FILE *file = fopen("input.txt", "rb"); // Open the input file in binary read mode
    if (file == NULL) {
        printf("Error opening file\n");
        return 1;
    }

    FILE *output_file = fopen("output.txt", "wb"); // Open the output file in binary write mode
    if (output_file == NULL) {
        printf("Error opening output file\n");
        fclose(file); // Close the input file
        return 1;
    }

    char buffer[1024]; // Define a buffer to read and store file contents

    int bytes_read = 0; // Initialize the number of bytes read
    int checksum = 0; // Initialize the checksum

    while (1) {
        size_t bytes_to_read = sizeof(buffer);
        if (fread(buffer, 1, bytes_to_read, file) < bytes_to_read) { // Read from the input file into the buffer
            break;
        }
        bytes_read += bytes_to_read; // Update the number of bytes read

        for (int i = 0; i < bytes_to_read; i++) {
            checksum ^= buffer[i]; // Calculate the XOR checksum of the buffer
        }
    }

    if (checksum == 0) { // Check if the checksum is 0
        printf("Buffer is empty\n");
    } else {
        printf("Bytes read: %d, Checksum: %x\n", bytes_read, checksum);
    }

    fseek(output_file, 0, SEEK_SET); // Move the output file pointer to the beginning
    fwrite(&bytes_read, sizeof(int), 1, output_file); // Write the number of bytes read to the output file
    fwrite(&checksum, sizeof(int), 1, output_file); // Write the checksum to the output file

    fclose(file); // Close the input file
    fclose(output_file); // Close the output file

    return 0;
}
```

This code reads the contents of a file into a buffer. It then calculates the checksum of the buffer using XOR operation. If the checksum is 0, it means that the buffer is empty. The number of bytes read and the checksum are saved to another file.

Please note that this code assumes that the input file contains ASCII characters (not binary data) and does not handle errors when reading or writing files.']

['Here is the C code that performs the task:

```c
#include <stdio.h>
#include <stdlib.h>

// Function to calculate the checksum of a buffer
int calculateChecksum(char* buffer, int size) {
    int checksum = 0;
    for(int i=0; i<size; i++) {
        checksum += (int)buffer[i];
    }
    return checksum;
}

int main() {
    FILE *file = fopen("input.txt", "r"); // Open the input file
    if(file == NULL) {
        printf("Error opening the file.\n");
        return 1;
    }

    fseek(file, 0, SEEK_END); // Move to the end of the file
    long fileSize = ftell(file);
    rewind(file); // Move back to the beginning

    char* buffer = (char*)malloc((fileSize+1)*sizeof(char));
    fread(buffer, sizeof(char), fileSize, file);

    int checksum = calculateChecksum(buffer, fileSize);
    if(checksum == 0) {
        printf("Buffer is empty.\n");
    } else {
        printf("CheckSum: %d\n", checksum);
    }

    FILE *outputFile = fopen("output.txt", "w"); // Open the output file
    if(outputFile == NULL) {
        printf("Error opening the output file.\n");
        return 1;
    }

    fprintf(outputFile, "%ld\n", fileSize); // Write the number of bytes read to the output file
    fprintf(outputFile, "%d\n", checksum); // Write the checksum to the output file

    free(buffer);
    fclose(file);
    fclose(outputFile);

    return 0;
}
```

This program reads a file named "input.txt" into memory. It then calculates the sum of all bytes in the buffer (which is the simple checksum). If this checksum is zero, it means the buffer was empty. The number of bytes read and the checksum are written to another file named "output.txt".']

