    "A": 10.99,
    "B": 9.99,
    "C": 14.99,
}

def get_price(product_code):
    return product_prices.get(product_code, "Product not found")

@app.route('/price', methods=['GET'])
def calculate_price():
    # Get the product code and quantity from the request
    product_code = request.args.get('product_code')
    quantity = int(request.args.get('quantity'))

    if product_code and quantity:
        price = get_price(product_code) * quantity
        return {'price': f"The total price for {product_code} is ${price:.2f}'}
