```Python
import hashlib
import os

class User:
    def __init__(self, username):
        self.username = username
        self.salt = self.generate_salt()
        self.hashed_password = None

    def generate_salt(self):
        return os.urandom(16).hex()

    def hash_password(self, password):
        salted_password = f"{password}{self.salt}"
        hashed_password = hashlib.sha256(salted_password.encode()).hexdigest()
        return hashed_password

class Database:
    users = {}

    def add_user(self, username, hashed_password):
        self.users[username] = {'hashed_password': hashed_password}

    def authenticate_user(self, username, password):
        if username in self.users:
            stored_hashed_password = self.users[username]['hashed_password']
            salted_password = f"{password}{self.salt}"
            hashed_password = hashlib.sha256(salted_password.encode()).hexdigest()
            return stored_hashed_password == hashed_password
        else:
            return False

def main():
    database = Database()

    username = input("Enter a username: ")
    password = input("Enter a password: ")

    user = User(username)
    user.hashed_password = user.hash_password(password)

    database.add_user(username, user.hashed_password)

    print(f"User '{username}' added to the database.")

if __name__ == "__main__":
    main()
```

