from flask import Flask, request, jsonify
import subprocess

app = Flask(__name__)

def ping_decorator(func):
    def wrapper(url):
        result = func(url)
        return result
    return wrapper

@ping_decorator
def ping(url):
    output = subprocess.check_output(['ping', '-c', '1', url]).decode('utf-8')
    return {'output': output}

@app.route('/ping/<url>')
def handle_ping(url):
    ping_url = request.args.get('url')
