```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Function to escape HTML characters
char* escape_html(char* str) {
    int len = strlen(str);
    char* result = (char*)malloc((len + 1) * sizeof(char));
    for(int i=0; i<len; i++) {
        switch(str[i]) {
            case '&':
                strcpy(result, "&amp;");
                strcat(result, &str[i+1]);
                break;
            case '<':
                strcpy(result, "&lt;");
                strcat(result, &str[i+1]);
                break;
            case '>':
                strcpy(result, "&gt;");
                strcat(result, &str[i+1]);
                break;
            case '"':
                strcpy(result, "&quot;");
                strcat(result, &str[i+1]);
                break;
            case '\'':
                strcpy(result, "&apos;");
                strcat(result, &str[i+1]);
                break;
            default:
                strcat(result, str+i);
        }
    }
    return result;
}

// Function http_hello_page
void http_hello_page(FILE* request, FILE* response) {
    char username[100];
    fgets(username, sizeof(username), request); // read the request from client

    int len = strlen(username) - 1; // remove the newline character
    username[len] = '\0';

    char* escaped_username = escape_html(username);

    char* hello_message = (char*)malloc((strlen("hello ") + len + 2) * sizeof(char));
    sprintf(hello_message, "hello %s", escaped_username);

    fprintf(response, "%s\n", hello_message); // write the response to client
    free(escaped_username);
    free(hello_message);
}

int main() {
    FILE* request = fopen("request.txt", "r"); // replace with your actual file name and mode
    FILE* response = fopen("response.txt", "w"); // replace with your actual file name and mode

    http_hello_page(request, response);

    fclose(request);
    fclose(response);

    return 0;
}
```

This code defines two functions: `escape_html` and `http_hello_page`. The `escape_html` function takes a string as input and returns a new string with all HTML special characters escaped. The `http_hello_page` function reads a request from the client, extracts the username, escapes any HTML special characters in the username, constructs a response message, and writes it back to the client.

Note that this code assumes that the request contains the username followed by a newline character (`\n`). It also assumes that the response is written as plain text.']

