from jinja2 import Template

class MyWebFramework:
    def __init__(self):
        self.env = {
            'hello.html': Template('Hello, {{ name }}!'),
            'goodbye.html': Template('Goodbye, {{ name }}!')
        }

    def render_response_from_env(self, env):
        name = request.args.get('name')
        template = env[request.full_path.split('/')[-1]]
        response = template.render(name=name)
        return response

    def home(self):
        return self.render_response_from_env(self.env)

# Usage:
my_web_framework = MyWebFramework()
response = my_web_framework.home()
print(response)  # Output: Hello, <name>!
```

